    counts_conn.close()
    status_counts = {k: 0 for k in BNI_CREDIT_STATUS_ORDER}
    for r in all_rows:
        k = _bni_credit_status_key(r["cert_status"], r["usage_status"])
        status_counts[k] = status_counts.get(k, 0) + 1

    return render_template(
        "bni_credit.html",
